from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color, q, pts = grid[r][c], deque([(r, c)]), set()
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                pts.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, pts))
    return out


def _boundary_l(points, h, w):
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    for r, vd in ((r0, 1), (r1, -1)):
        for c, hd in ((c0, 1), (c1, -1)):
            expected = ({(r, x) for x in range(c0, c1 + 1)} |
                        {(y, c) for y in range(r0, r1 + 1)})
            if points != expected:
                continue
            # The free end of each arm reaches a different grid edge.
            vertical_end = r1 if vd == 1 else r0
            horizontal_end = c1 if hd == 1 else c0
            if vertical_end in (0, h - 1) and horizontal_end in (0, w - 1):
                return r, c, vd, hd, r1 - r0, c1 - c0
    return None


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    for color, marker in comps:
        m = _boundary_l(marker, h, w)
        if not m:
            continue
        r, c, vd, hd, vl, hl = m
        if hl > vl:
            sv, sh = -vd, hd
            projection_axis = "vertical"
        elif vl > hl:
            sv, sh = vd, -hd
            projection_axis = "horizontal"
        else:
            continue
        candidates = []
        for other_color, pts in comps:
            if pts == marker:
                continue
            ys, xs = [y for y, x in pts], [x for y, x in pts]
            cy, cx = sum(ys) / len(ys), sum(xs) / len(xs)
            if (cy - r) * sv > 0 and (cx - c) * sh > 0:
                if projection_axis == "vertical":
                    projection = max((y - r) * sv for y, x in pts)
                else:
                    projection = max((x - c) * sh for y, x in pts)
                candidates.append((projection, len(pts), pts))
        if candidates:
            target = max(candidates, key=lambda z: (z[0], z[1]))[2]
            out = [row[:] for row in grid]
            for y, x in target:
                out[y][x] = color
            return out
    return [row[:] for row in grid]
